import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;
import java.util.regex.Pattern;

public class AssetLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetLookupServlet.class.getName());
    private static final Pattern ASSET_ID_FORMAT = Pattern.compile("^[A-Z]{2}-\\d{4,12}$");

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String assetId = req.getParameter("asset_id");
        String fields = req.getParameter("fields");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (assetId == null || tenantId == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate asset ID format
        if (!ASSET_ID_FORMAT.matcher(assetId).matches()) {
            resp.sendError(400, "Invalid asset_id format");
            return;
        }

        // Validate tenant header is numeric
        try {
            Long.parseLong(tenantId);
        } catch (NumberFormatException e) {
            resp.sendError(400, "Invalid tenant ID");
            return;
        }

        // Default fields if not specified
        if (fields == null || fields.isEmpty()) {
            fields = "asset_name, status, location";
        }

        // Restrict field length to prevent abuse
        if (fields.length() > 200) {
            resp.sendError(400, "Fields parameter too long");
            return;
        }

        // Build query - fields are column names from a controlled dropdown in the UI
        String query = "SELECT " + fields + " FROM assets WHERE asset_id = ? AND tenant_id = ?";

        log.info("Asset lookup: tenant=" + tenantId + " asset=" + assetId);

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, assetId);
            stmt.setString(2, tenantId);

            ResultSet rs = stmt.executeQuery();
            ResultSetMetaData meta = rs.getMetaData();

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{\"results\":[");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\":");
                    String val = rs.getString(i);
                    json.append(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
